DROP TABLE IF EXISTS students;

CREATE TABLE students (
    id INTEGER PRIMARY KEY,
    firstname VARCHAR(50) NOT NULL,
    lastname VARCHAR(50) NOT NULL,
    username VARCHAR(100) NOT NULL UNIQUE,
    birthday DATE NOT NULL,
    class VARCHAR(3) NOT NULL,
    average DECIMAL(3,2),
    height INTEGER,
    siblings INTEGER DEFAULT 0,
    image VARCHAR(255),

    CHECK (class IN (
        '9A','9B','9C','9D',
        '10A','10B','10C','10D',
        '11A','11B','11C','11D',
        '12A','12B','12C','12D'
    )),
    CHECK (average IS NULL OR average BETWEEN 1.00 AND 5.00),
    CHECK (height IS NULL OR height BETWEEN 120 AND 230),
    CHECK (siblings >= 0)
);

